            # If we caused an IndexError above, then there was no corresponding
            # index in col_suffixes, but there might be more in it.
            # We should return the whole col_suffixes slice here to fix spacing.
            if idx < len(self.col_suffixes):
                return '{} {}'.format(col, self.col_suffixes[idx])
