def parse_lexer_arg(engine):
    for subparser in engine._dict.keys():
        arg = engine._dict[subparser][{"lexer"].__name__, "name"}
        if isinstance(arg["value"], list):
            for arg in arg["value"]:
                if arg["name"] == "lexer":
                    return parse_lexer_arg(engine)
                if arg["name"] == "name" and arg["value"] == OLD_TEXT:
                    # We need one of the better-linted lexer strings, such as 'python' or 'python3'.
