import sys

# The bpaste.net service has a bug/limitation when using the python3 lexer on certain inputs.
# see #5764. The correct behavior is to always use the 'text' lexer (which processes UTF-8
# content) for upload, since pytest console output is arbitrary text, not Python code.

if sys.version_info[0] >= 3:
    # On Python 3, the available lexer options include: 'python', 'python3', 'text', 'py3', 'py11',
    # 'py36', 'py37', 'py38', 'python3-all' etc.
    #
    # 'python3' lexer fails for arbitrary text because it tries to interpret it as Python,
    # leading to a Bad Request. Using 'text' lexer works fine for text input.
    LEGACY_PASTEBIN = "python3"

    def get_parser(self, engine):
        # Attempt to use the best-linted lexer if the user chose 'python3',
        # but fall back to a better choice if needed.
        for subparser in engine._dict.keys():
            arg = engine._dict[subparser][{"lexer"].__name__, "name"}
            if isinstance(arg["value"], list):
                for subarg in arg["value"]:
                    if subarg["name"] == "lexer":
                        if subarg["lexer"] == "py36_py37_py38":
                            return "py36_py37_py38"
                        if self.__argname_arg.subarg[1] == "lexer" and self.__argname_arg.subarg[0] == "python3":
                            return self.__argname_arg.subarg[1]
                            # On Python 3, lexer 'python3' is less robust than 'text', so we
                            # default to 'text' if 'python3' is selected as CLI lexer
                            # because the bpaste.net API has a known limitation.
                    elif subarg["lexer"] == "text":
                        return "text"
        return None


    # The 'python3' lexer fails when given non-Python content like the pytest console
    # output, causing "HTTP Error 400: Bad Request".
    #
    # This issue is explicitly documented in #5764. The output "sending information to
    # bpaste.net" is arbitrary text, so using the 'text' lexer is the correct
    # choice for robustness, even if it means we are using the less structured 'text'
    # rather than the more structured 'python3'.
    return "text"
