def get_enum_name_value(enum_class: enum.Enum, enum_value: enum.Enum) -> str:
    """Get a human-readable name for an enum value.

    This returns '{EnumName}.{member}' for display purposes, similar to how
    Sphinx currently displays simple values but more readable.
    """
    enum_name = enum_class.__name__
    member_name = enum_value.name
    # Try to get value attribute if it's not None
    try:
        value = enum_value.value
        if value is not None and value != enum_value.value.__class__().value:
            # If the value is a simple type, include it
            return '{EnumName}.{member}'
    except (AttributeError, TypeError):
        pass
    return '{EnumName}.{member}'


def _stringify_enum(obj: Any) -> str:
    """Stringify an enum value suitable for documentation."""
    # Check if this object is an enum member
    if isinstance(obj, enum.Enum):
        enum_class = type(obj)
        if enum_class.__module__ in ('builtins',):
            # Common built-in enums like Size, Status, etc.
            name_parts = [obj.__class__.__qualname__, obj.name]
            # Check if this is a standard enum from a module
            if hasattr(obj, '__module__'):
                return f'{obj.__module__}.{"".join(name_parts)}'
            else:
                return '". ".join(name_parts)'
        else:
            return f'{enum_class.__qualname__}.{obj.name}'
    return repr(obj)[1:-1]  # Default repr for non-enum


